__global__ void __launch_bounds__(256, 1)
probe_ss_n256_mnmajor(int reps, int active_wg, unsigned long long* out, float* sink) {
    extern __shared__ __align__(1024) unsigned char smem[];
    const int wg = threadIdx.x / 128;
    const uint32_t base = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
    float d[N / 2];
    #pragma unroll
    for (int i = 0; i < N / 2; ++i) d[i] = 0.f;
    uint32_t a[4] = {threadIdx.x * 0x00010001u, 0x3f803f80u, 0x3f003f00u, threadIdx.x};
    // A: 64 rows x K (K-major, 128B swizzle atoms of 64 elements), B after 64 KiB.
    const uint32_t a_base = base;
    const uint32_t b_base = base + 64 * 1024;
    __syncthreads();
    unsigned long long start = 0, stop = 0;
    if (wg < active_wg) {
        start = clock64();
        for (int r = 0; r < reps; ++r) {
            wg_fence();
            #pragma unroll
            for (int k = 0; k < KSTEPS; ++k) {
                const uint32_t k_off_a = (k % 4) * 32 + (k / 4) * (64 * 128);
                const uint64_t desc_b = TRANSB
                    ? make_desc(b_base + (k % 8) * 2048, 8192, 1024)
                    : make_desc(b_base + (k % 4) * 32 + ((k / 4) % 4) * (N * 128), 16, 1024);
                if constexpr (RS) {
                    /*unused*/(void)(a, desc_b, (r | k) != 0);
                } else {
                    const uint64_t desc_a = make_desc(a_base + (k_off_a % (64 * 1024)), 16, 1024);
                    wgmma_ss_n256_mnmajor(d, desc_a, desc_b, (r | k) != 0);
                }
            }
            wg_commit();
            wg_wait0();
        }
        stop = clock64();
    }
    float acc = 0.f;
    #pragma unroll
    for (int i = 0; i < N / 2; ++i) acc += d[i];
    if (acc == 1234.5f) sink[threadIdx.x] = acc;
    if (wg < active_wg && threadIdx.x % 128 == 0) {
        out[(blockIdx.x * 2 + wg) * 2 + 0] = start;
        out[(blockIdx.x * 2 + wg) * 2 + 1] = stop;
    }
}

template <int N, bool RS, int TRANSB, int KSTEPS>
__global__ void __launch_bounds__(256, 1)
probe_rs_n256_mnmajor(int reps, int active_wg, unsigned long long* out, float* sink) {
    extern __shared__ __align__(1024) unsigned char smem[];
    const int wg = threadIdx.x / 128;
    const uint32_t base = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
    float d[N / 2];
    #pragma unroll
    for (int i = 0; i < N / 2; ++i) d[i] = 0.f;
    uint32_t a[4] = {threadIdx.x * 0x00010001u, 0x3f803f80u, 0x3f003f00u, threadIdx.x};
    // A: 64 rows x K (K-major, 128B swizzle atoms of 64 elements), B after 64 KiB.
    const uint32_t a_base = base;
    const uint32_t b_base = base + 64 * 1024;
    __syncthreads();
    unsigned long long start = 0, stop = 0;
    if (wg < active_wg) {
        start = clock64();
        for (int r = 0; r < reps; ++r) {
            wg_fence();
            #pragma unroll
            for (int k = 0; k < KSTEPS; ++k) {
                const uint32_t k_off_a = (k % 4) * 32 + (k / 4) * (64 * 128);
                const uint64_t desc_b = TRANSB
                    ? make_desc(b_base + (k % 8) * 2048, 8192, 1024)
                    : make_desc(b_base + (k % 4) * 32 + ((k / 4) % 4) * (N * 128), 16, 1024);
                if constexpr (RS) {
                    wgmma_rs_n256_mnmajor(d, a, desc_b, (r | k) != 0);
                } else {
                    const uint64_t desc_a = make_desc(a_base + (k_off_a % (64 * 1024)), 16, 1024);
                    /*unused*/(void)(desc_a, desc_b, (r | k) != 0);
                }
            }
            wg_commit();
            wg_wait0();
        }
        stop = clock64();
    }
    float acc = 0.f;
    #pragma unroll
    for (int i = 0; i < N / 2; ++i) acc += d[i];
    if (acc == 1234.5f) sink[threadIdx.x] = acc;
    if (wg < active_wg && threadIdx.x % 128 == 0) {
        out[(blockIdx.x * 2 + wg) * 2 + 0] = start;
        out[(blockIdx.x * 2 + wg) * 2 + 1] = stop;
    }
}

template <typename Kernel>
static void run(Kernel kernel, const char* shape, int ksteps, int active_wg, int grid, int reps) {
    CHECK(cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemBytes));
    unsigned long long* out = nullptr; float* sink = nullptr;
    CHECK(cudaMalloc(&out, sizeof(unsigned long long) * grid * 4));
    CHECK(cudaMalloc(&sink, sizeof(float) * 256));
    CHECK(cudaMemset(out, 0, sizeof(unsigned long long) * grid * 4));
    kernel<<<grid, 256, kSmemBytes>>>(reps, active_wg, out, sink);  // warm-up
    CHECK(cudaGetLastError()); CHECK(cudaDeviceSynchronize());
    kernel<<<grid, 256, kSmemBytes>>>(reps, active_wg, out, sink);
    CHECK(cudaGetLastError()); CHECK(cudaDeviceSynchronize());
    std::vector<unsigned long long> host(grid * 4);
    CHECK(cudaMemcpy(host.data(), out, sizeof(unsigned long long) * grid * 4, cudaMemcpyDeviceToHost));
    std::printf("shape,ksteps,active_wg,grid,reps,cta,wg,cycles\n");
    for (int c = 0; c < grid; ++c)
        for (int w = 0; w < active_wg; ++w)
            std::printf("%s,%d,%d,%d,%d,%d,%d,%llu\n", shape, ksteps, active_wg, grid, reps, c, w,
                        host[(c * 2 + w) * 2 + 1] - host[(c * 2 + w) * 2 + 0]);
    CHECK(cudaFree(out)); CHECK(cudaFree(sink));
}

int main(int argc, char** argv) {
    if (argc != 6) { std::fprintf(stderr, "usage: %s SHAPE KSTEPS ACTIVE_WG GRID REPS\n", argv[0]); return 1; }
    const char* shape = argv[1];
    const int ksteps = std::atoi(argv[2]), active_wg = std::atoi(argv[3]);
    const int grid = std::atoi(argv[4]), reps = std::atoi(argv[5]);
    if (active_wg < 1 || active_wg > 2 || grid < 1 || reps < 1) { std::fprintf(stderr, "bad args\n"); return 1; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 1) { run(probe_ss_n64_kmajor<64, false, 0, 1>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 2) { run(probe_ss_n64_kmajor<64, false, 0, 2>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 4) { run(probe_ss_n64_kmajor<64, false, 0, 4>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 8) { run(probe_ss_n64_kmajor<64, false, 0, 8>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 12) { run(probe_ss_n64_kmajor<64, false, 0, 12>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 32) { run(probe_ss_n64_kmajor<64, false, 0, 32>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n64_kmajor") && ksteps == 36) { run(probe_ss_n64_kmajor<64, false, 0, 36>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 1) { run(probe_ss_n128_kmajor<128, false, 0, 1>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 2) { run(probe_ss_n128_kmajor<128, false, 0, 2>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 4) { run(probe_ss_n128_kmajor<128, false, 0, 4>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 8) { run(probe_ss_n128_kmajor<128, false, 0, 8>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 12) { run(probe_ss_n128_kmajor<128, false, 0, 12>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 32) { run(probe_ss_n128_kmajor<128, false, 0, 32>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n128_kmajor") && ksteps == 36) { run(probe_ss_n128_kmajor<128, false, 0, 36>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 1) { run(probe_rs_n128_mnmajor<128, true, 1, 1>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 2) { run(probe_rs_n128_mnmajor<128, true, 1, 2>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 4) { run(probe_rs_n128_mnmajor<128, true, 1, 4>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 8) { run(probe_rs_n128_mnmajor<128, true, 1, 8>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 12) { run(probe_rs_n128_mnmajor<128, true, 1, 12>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 32) { run(probe_rs_n128_mnmajor<128, true, 1, 32>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n128_mnmajor") && ksteps == 36) { run(probe_rs_n128_mnmajor<128, true, 1, 36>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 1) { run(probe_ss_n256_mnmajor<256, false, 1, 1>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 2) { run(probe_ss_n256_mnmajor<256, false, 1, 2>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 4) { run(probe_ss_n256_mnmajor<256, false, 1, 4>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 8) { run(probe_ss_n256_mnmajor<256, false, 1, 8>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 12) { run(probe_ss_n256_mnmajor<256, false, 1, 12>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 32) { run(probe_ss_n256_mnmajor<256, false, 1, 32>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "ss_n256_mnmajor") && ksteps == 36) { run(probe_ss_n256_mnmajor<256, false, 1, 36>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 1) { run(probe_rs_n256_mnmajor<256, true, 1, 1>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 2) { run(probe_rs_n256_mnmajor<256, true, 1, 2>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 4) { run(probe_rs_n256_mnmajor<256, true, 1, 4>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 8) { run(probe_rs_n256_mnmajor<256, true, 1, 8>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 12) { run(probe_rs_n256_mnmajor<256, true, 1, 12>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 32) { run(probe_rs_n256_mnmajor<256, true, 1, 32>, shape, ksteps, active_wg, grid, reps); return 0; }
    if (!std::strcmp(shape, "rs_n256_mnmajor") && ksteps == 36) { run(probe_rs_n256_mnmajor<256, true, 1, 36>, shape, ksteps, active_wg, grid, reps); return 0; }
    std::fprintf(stderr, "unknown shape/ksteps\n");
    return 1;
}

